      <button class="btn" id="btnMaze">Labirin Acak</button>
      <button class="btn" id="btnClear">Bersihkan</button>
    </div>
  </div>

  <div class="stats">
    <div class="stat">Petak dijelajahi: <b id="statVisited">&mdash;</b></div>
