    <span><i class="sw" style="background:#e8544c"></i>Tujuan</span>
    <span><i class="sw" style="background:#3a4a63"></i>Dinding</span>
    <span><i class="sw" style="background:#6e4a1e"></i>Lumpur (biaya 5)</span>
    <span><i class="sw" style="background:#1c5a75"></i>Dijelajahi</span>
    <span><i class="sw" style="background:#f2c14e"></i>Jalur akhir</span>
  </div>
