</style>
</head>
<body>
<div id="stage">
  <canvas id="sky" aria-label="Simulasi tata surya beranimasi"></canvas>

  <aside class="info" id="info" hidden aria-live="polite">
    <button class="tutup" id="infoTutup" type="button" aria-label="Tutup info">&times;</button>
    <h2 id="infoNama">&mdash;</h2>
    <dl>
      <dt>Diameter</dt><dd id="infoDiameter">&mdash;</dd>
      <dt id="dtJarak">Jarak ke Matahari</dt><dd id="infoJarak">&mdash;</dd>
      <dt>Periode orbit</dt><dd id="infoPeriode">&mdash;</dd>
    </dl>
  </aside>

  <div class="kontrol" role="group" aria-label="Kontrol simulasi">
    <button id="btnJeda" type="button" aria-pressed="false">Jeda</button>
    <div class="slider">
      <label for="kecepatan">Kecepatan waktu <span id="nilaiKecepatan">1,0&times;</span></label>
      <input id="kecepatan" type="range" min="0.1" max="8" step="0.1" value="1" aria-label="Kecepatan waktu">
    </div>
    <div class="zoom">
      <button id="btnZoomOut" type="button" aria-label="Perkecil tampilan">&minus;</button>
      <button id="btnZoomIn" type="button" aria-label="Perbesar tampilan">+</button>
      <button id="btnPusat" type="button">Pusatkan</button>
    </div>
    <span class="petunjuk">Klik planet untuk info &middot; scroll / cubit untuk zoom &middot; geser untuk menggeser</span>
  </div>
</div>

<script>
(function () {
  'use strict';

  /* ============ Referensi DOM ============ */
  var canvas = document.getElementById('sky');
  var ctx = canvas.getContext('2d');
  var infoEl = document.getElementById('info');
  var elNama = document.getElementById('infoNama');
  var elDiameter = document.getElementById('infoDiameter');
  var elJarak = document.getElementById('infoJarak');
  var elPeriode = document.getElementById('infoPeriode');
  var elDtJarak = document.getElementById('dtJarak');
  var btnTutup = document.getElementById('infoTutup');
  var btnJeda = document.getElementById('btnJeda');
  var slider = document.getElementById('kecepatan');
  var elNilai = document.getElementById('nilaiKecepatan');
  var btnZoomIn = document.getElementById('btnZoomIn');
  var btnZoomOut = document.getElementById('btnZoomOut');
  var btnPusat = document.getElementById('btnPusat');

  /* ============ Penyimpanan lokal aman ============ */
  function simpan(kunci, nilai) {
    try { window.localStorage.setItem(kunci, nilai); } catch (e) { /* diabaikan */ }
  }
  function baca(kunci) {
    try { return window.localStorage.getItem(kunci); } catch (e) { return null; }
  }

  /* ============ Data tata surya ============ */
  var TAHUN_DETIK = 8; // detik nyata untuk 1 tahun Bumi pada kecepatan 1x

  var PLANET = [
    { nama: 'Merkurius', orbit: 85,  radius: 3.0, warna: '#b3a49a', periode: 88,
      diameter: '4.879 km',   jarak: '57,9 juta km',    waktuOrbit: '88 hari',     sudut0: 0.40 },
    { nama: 'Venus',     orbit: 129, radius: 4.6, warna: '#e0b978', periode: 224.7,
      diameter: '12.104 km',  jarak: '108,2 juta km',   waktuOrbit: '224,7 hari',  sudut0: 2.10 },
    { nama: 'Bumi',      orbit: 180, radius: 5.0, warna: '#4f8fe0', periode: 365.25,
      diameter: '12.742 km',  jarak: '149,6 juta km',   waktuOrbit: '365,25 hari', sudut0: 4.00 },
    { nama: 'Mars',      orbit: 237, radius: 3.8, warna: '#c1553c', periode: 687,
      diameter: '6.779 km',   jarak: '227,9 juta km',   waktuOrbit: '687 hari',    sudut0: 5.40 },
    { nama: 'Jupiter',   orbit: 298, radius: 12,  warna: '#c9a483', periode: 4333,
      diameter: '139.820 km', jarak: '778,5 juta km',   waktuOrbit: '11,86 tahun', sudut0: 1.20 },
    { nama: 'Saturnus',  orbit: 365, radius: 10,  warna: '#d9c18a', periode: 10759, cincin: true,
      diameter: '116.460 km', jarak: '1,43 miliar km',  waktuOrbit: '29,46 tahun', sudut0: 3.30 },
    { nama: 'Uranus',    orbit: 436, radius: 7,   warna: '#8fd8dd', periode: 30687,
      diameter: '50.724 km',  jarak: '2,87 miliar km',  waktuOrbit: '84,0 tahun',  sudut0: 5.90 },
    { nama: 'Neptunus',  orbit: 511, radius: 6.8, warna: '#5a7fe0', periode: 60190,
      diameter: '49.244 km',  jarak: '4,50 miliar km',  waktuOrbit: '164,8 tahun', sudut0: 0.90 }
  ];

  for (var i = 0; i < PLANET.length; i++) {
    var p = PLANET[i];
    p.omega = (Math.PI * 2) / ((p.periode / 365.25) * TAHUN_DETIK);
    p._x = 0; p._y = 0;
  }

  var BULAN = {
    nama: 'Bulan', radius: 2.0, orbit: 17, warna: '#cfd6e2', induk: 2,
    diameter: '3.474 km', jarak: '384.400 km', labelJarak: 'Jarak ke Bumi',
    waktuOrbit: '27,3 hari', sudut0: 1.0
  };
  // Dipercepat agar gerak mengelilingi Bumi tetap terlihat (5 putaran per tahun Bumi).
  BULAN.omega = (Math.PI * 2) / 1.6;
  BULAN._x = 0; BULAN._y = 0;

  var KANDIDAT = PLANET.concat([BULAN]);

  /* ============ State ============ */
  var W = 0, H = 0, DPR = 1;
  var waktu = 0;
  var kecepatan = 1;
  var jeda = false;
  var terpilih = null;
  var autoFit = true;
  var bintang = [];
  var cam = { x: 0, y: 0, zoom: 0.35 };
  var last = 0;

  /* ============ Utilitas warna ============ */
  function rgba(hex, a) {
    var n = parseInt(hex.slice(1), 16);
    return 'rgba(' + ((n >> 16) & 255) + ',' + ((n >> 8) & 255) + ',' + (n & 255) + ',' + a + ')';
  }
  function cerah(hex, t) {
    var n = parseInt(hex.slice(1), 16);
    var r = (n >> 16) & 255, g = (n >> 8) & 255, b = n & 255;
    return 'rgb(' + Math.round(r + (255 - r) * t) + ',' +
                    Math.round(g + (255 - g) * t) + ',' +
                    Math.round(b + (255 - b) * t) + ')';
  }
  function batas(v, lo, hi) { return v < lo ? lo : (v > hi ? hi : v); }

  /* ============ Ukuran kanvas ============ */
  function hitungZoomAwal() {
    return batas(Math.min(W, H) / 1150, 0.18, 1.4);
  }

  function buatBintang() {
    bintang = [];
    var n = Math.round(batas((W * H) / 2600, 60, 260));
    for (var i = 0; i < n; i++) {
      bintang.push({
        x: Math.random() * W,
        y: Math.random() * H,
        r: Math.random() * 1.1 + 0.25,
        a: Math.random() * 0.55 + 0.22,
        ph: Math.random() * Math.PI * 2
      });
    }
  }

  function ukur() {
    DPR = Math.min(window.devicePixelRatio || 1, 2);
    W = canvas.clientWidth || window.innerWidth;
    H = canvas.clientHeight || window.innerHeight;
    canvas.width = Math.max(1, Math.round(W * DPR));
    canvas.height = Math.max(1, Math.round(H * DPR));
    ctx.setTransform(DPR, 0, 0, DPR, 0, 0);
    buatBintang();
    if (autoFit) {
      cam.x = 0; cam.y = 0;
      cam.zoom = hitungZoomAwal();
    }
  }

  /* ============ Posisi ============ */
  function hitungPosisi() {
    for (var i = 0; i < PLANET.length; i++) {
      var p = PLANET[i];
      var a = p.sudut0 + p.omega * waktu;
      p._x = Math.cos(a) * p.orbit;
      p._y = Math.sin(a) * p.orbit;
    }
    var bumi = PLANET[BULAN.induk];
    var am = BULAN.sudut0 + BULAN.omega * waktu;
    BULAN._x = bumi._x + Math.cos(am) * BULAN.orbit;
    BULAN._y = bumi._y + Math.sin(am) * BULAN.orbit;
  }

  /* ============ Menggambar ============ */
  function gambarBintang(now) {
    for (var i = 0; i < bintang.length; i++) {
      var s = bintang[i];
      var tw = 0.62 + 0.38 * Math.sin(now * 0.0012 + s.ph);
      ctx.globalAlpha = s.a * tw;
      ctx.fillStyle = '#cfe0ff';
      ctx.beginPath();
      ctx.arc(s.x, s.y, s.r, 0, Math.PI * 2);
      ctx.fill();
    }
    ctx.globalAlpha = 1;
  }

  function gambarMatahari() {
    var r = 16;
    var g = ctx.createRadialGradient(0, 0, 0, 0, 0, r * 4.2);
    g.addColorStop(0, 'rgba(255,246,214,0.95)');
    g.addColorStop(0.18, 'rgba(255,200,90,0.72)');
    g.addColorStop(0.45, 'rgba(255,150,40,0.18)');
    g.addColorStop(1, 'rgba(255,120,20,0)');
    ctx.fillStyle = g;
    ctx.beginPath();
    ctx.arc(0, 0, r * 4.2, 0, Math.PI * 2);
    ctx.fill();

    var g2 = ctx.createRadialGradient(-r * 0.25, -r * 0.25, r * 0.1, 0, 0, r);
    g2.addColorStop(0, '#fffdf0');
    g2.addColorStop(0.6, '#ffd45e');
    g2.addColorStop(1, '#ff9a1f');
    ctx.fillStyle = g2;
    ctx.beginPath();
    ctx.arc(0, 0, r, 0, Math.PI * 2);
    ctx.fill();
  }

  function gambarCincin(p, depan) {
    var r = p.radius;
    var a0 = depan ? 0 : Math.PI;
    var a1 = depan ? Math.PI : Math.PI * 2;
    var band = [[1.35, 1.62, 0.55], [1.70, 2.15, 0.34]];
    for (var i = 0; i < band.length; i++) {
      var i0 = band[i][0], i1 = band[i][1], al = band[i][2];
      var rr = r * (i0 + i1) / 2;
      ctx.beginPath();
      ctx.ellipse(p._x, p._y, rr, rr * 0.32, 0, a0, a1);
      ctx.lineWidth = r * (i1 - i0);
      ctx.strokeStyle = 'rgba(226,206,160,' + al + ')';
      ctx.stroke();
    }
  }

  function gambarPlanet(p) {
    var x = p._x, y = p._y, r = p.radius;

    if (p.cincin) gambarCincin(p, false);

    var g = ctx.createRadialGradient(x, y, 0, x, y, r * 2.8);
    g.addColorStop(0, rgba(p.warna, 0.30));
    g.addColorStop(1, rgba(p.warna, 0));
    ctx.fillStyle = g;
    ctx.beginPath();
    ctx.arc(x, y, r * 2.8, 0, Math.PI * 2);
    ctx.fill();

    var b = ctx.createRadialGradient(x - r * 0.35, y - r * 0.35, r * 0.12, x, y, r);
    b.addColorStop(0, cerah(p.warna, 0.45));
    b.addColorStop(1, p.warna);
    ctx.fillStyle = b;
    ctx.beginPath();
    ctx.arc(x, y, r, 0, Math.PI * 2);
    ctx.fill();

    if (p.cincin) gambarCincin(p, true);

    if (cam.zoom >= 0.55 || terpilih === p) {
      var fs = 11 / cam.zoom;
      ctx.font = '600 ' + fs + 'px system-ui, sans-serif';
      ctx.textAlign = 'center';
      ctx.textBaseline = 'bottom';
      ctx.fillStyle = terpilih === p ? 'rgba(180,225,255,0.95)' : 'rgba(205,222,250,0.78)';
      ctx.fillText(p.nama, x, y - r - 6 / cam.zoom);
    }
  }

  function gambarBulan() {
    var x = BULAN._x, y = BULAN._y, r = BULAN.radius;
    var g = ctx.createRadialGradient(x, y, 0, x, y, r * 3);
    g.addColorStop(0, 'rgba(200,215,240,0.28)');
    g.addColorStop(1, 'rgba(200,215,240,0)');
    ctx.fillStyle = g;
    ctx.beginPath();
    ctx.arc(x, y, r * 3, 0, Math.PI * 2);
    ctx.fill();

    ctx.fillStyle = '#cfd6e2';
    ctx.beginPath();
    ctx.arc(x, y, r, 0, Math.PI * 2);
    ctx.fill();
  }

  function gambarSorot(obj) {
    ctx.beginPath();
    ctx.arc(obj._x, obj._y, obj.radius + 7 / cam.zoom, 0, Math.PI * 2);
    ctx.strokeStyle = 'rgba(127,209,255,0.9)';
    ctx.lineWidth = 1.6 / cam.zoom;
    ctx.stroke();
  }

  function gambar(now) {
    ctx.setTransform(DPR, 0, 0, DPR, 0, 0);

    var bg = ctx.createLinearGradient(0, 0, 0, H);
    bg.addColorStop(0, '#05070f');
    bg.addColorStop(1, '#080c18');
    ctx.fillStyle = bg;
    ctx.fillRect(0, 0, W, H);

    gambarBintang(now);

    ctx.save();
    ctx.translate(W / 2 + cam.x, H / 2 + cam.y);
    ctx.scale(cam.zoom, cam.zoom);

    ctx.lineWidth = 1 / cam.zoom;
    ctx.strokeStyle = 'rgba(110,150,230,0.16)';
    for (var i = 0; i < PLANET.length; i++) {
      ctx.beginPath();
      ctx.arc(0, 0, PLANET[i].orbit, 0, Math.PI * 2);
      ctx.stroke();
    }

    var bumi = PLANET[BULAN.induk];
    ctx.strokeStyle = 'rgba(150,170,210,0.14)';
    ctx.beginPath();
    ctx.arc(bumi._x, bumi._y, BULAN.orbit, 0, Math.PI * 2);
    ctx.stroke();

    gambarMatahari();
    for (var j = 0; j < PLANET.length; j++) gambarPlanet(PLANET[j]);
    gambarBulan();
    if (terpilih) gambarSorot(terpilih);

    ctx.restore();
  }

  /* ============ Info planet ============ */
  function tampilkanInfo(o) {
    elNama.textContent = o.nama;
    elDiameter.textContent = o.diameter;
    elDtJarak.textContent = o.labelJarak || 'Jarak ke Matahari';
    elJarak.textContent = o.jarak;
    elPeriode.textContent = o.waktuOrbit;
    infoEl.hidden = false;
  }

  function sembunyikanInfo() {
    terpilih = null;
    infoEl.hidden = true;
  }

  /* ============ Kamera & interaksi ============ */
  function posLokal(e) {
    var r = canvas.getBoundingClientRect();
    return { x: e.clientX - r.left, y: e.clientY - r.top };
  }

  function zoomPada(sx, sy, faktor) {
    var nz = batas(cam.zoom * faktor, 0.12, 14);
    if (nz === cam.zoom) return;
    var k = nz / cam.zoom;
    cam.x = sx - W / 2 - (sx - W / 2 - cam.x) * k;
    cam.y = sy - H / 2 - (sy - H / 2 - cam.y) * k;
    cam.zoom = nz;
    autoFit = false;
  }

  function keLayar(o) {
    return { x: W / 2 + cam.x + o._x * cam.zoom, y: H / 2 + cam.y + o._y * cam.zoom };
  }

  function cariObjek(sx, sy) {
    var best = null, bestD = Infinity;
    for (var i = 0; i < KANDIDAT.length; i++) {
      var o = KANDIDAT[i];
      var s = keLayar(o);
      var d = Math.hypot(s.x - sx, s.y - sy);
      var tol = Math.max(o.radius * cam.zoom, 5) + 14;
      if (d <= tol && d < bestD) { bestD = d; best = o; }
    }
    return best;
  }

  function pilihDi(sx, sy) {
    var o = cariObjek(sx, sy);
    if (o) {
      terpilih = o;
      tampilkanInfo(o);
    } else {
      sembunyikanInfo();
    }
  }

  function perbaruiKursor(sx, sy) {
    canvas.style.cursor = cariObjek(sx, sy) ? 'pointer' : 'grab';
  }

  /* --- Pointer (mouse + sentuh, termasuk pinch) --- */
  var pointers = new Map();
  var drag = null;
  var pinch = null;

  canvas.addEventListener('pointerdown', function (e) {
    var p = posLokal(e);
    pointers.set(e.pointerId, p);
    try { canvas.setPointerCapture(e.pointerId); } catch (err) { /* diabaikan */ }

    if (pointers.size === 1) {
      drag = { x: p.x, y: p.y, sx: p.x, sy: p.y, gerak: false, mulai: Date.now() };
      pinch = null;
    } else if (pointers.size === 2) {
      drag = null;
      var it = pointers.values();
      var a = it.next().value, b = it.next().value;
      pinch = {
        jarak: Math.hypot(a.x - b.x, a.y - b.y),
        cx: (a.x + b.x) / 2,
        cy: (a.y + b.y) / 2
      };
    }
  });

  canvas.addEventListener('pointermove', function (e) {
    var p = posLokal(e);

    if (!pointers.has(e.pointerId)) {
      perbaruiKursor(p.x, p.y);
      return;
    }
    pointers.set(e.pointerId, p);

    if (pointers.size >= 2 && pinch) {
      var it = pointers.values();
      var a = it.next().value, b = it.next().value;
      var d = Math.hypot(a.x - b.x, a.y - b.y);
      var cx = (a.x + b.x) / 2, cy = (a.y + b.y) / 2;
      if (pinch.jarak > 0 && d > 0) zoomPada(cx, cy, d / pinch.jarak);
      cam.x += cx - pinch.cx;
      cam.y += cy - pinch.cy;
      autoFit = false;
      pinch.jarak = d; pinch.cx = cx; pinch.cy = cy;
    } else if (drag) {
      var dx = p.x - drag.x, dy = p.y - drag.y;
      cam.x += dx;
      cam.y += dy;
      drag.x = p.x;
      drag.y = p.y;
      if (Math.hypot(p.x - drag.sx, p.y - drag.sy) > 6) drag.gerak = true;
      if (drag.gerak) autoFit = false;
    }
  });

  function akhiriPointer(e) {
    var p = pointers.get(e.pointerId);
    pointers.delete(e.pointerId);
    if (canvas.hasPointerCapture && canvas.hasPointerCapture(e.pointerId)) {
      try { canvas.releasePointerCapture(e.pointerId); } catch (err) { /* diabaikan */ }
    }
    if (pointers.size < 2) pinch = null;

    var bisaKlik = !!(p && drag && !drag.gerak && pointers.size === 0 &&
                      (Date.now() - drag.mulai) < 700);
    if (bisaKlik) pilihDi(p.x, p.y);

    drag = null;
    if (pointers.size === 1) {
      var sisa = pointers.values().next().value;
      drag = { x: sisa.x, y: sisa.y, sx: sisa.x, sy: sisa.y, gerak: true, mulai: Date.now() };
    }
  }

  canvas.addEventListener('pointerup', akhiriPointer);
  canvas.addEventListener('pointercancel', function (e) {
    pointers.delete(e.pointerId);
    if (pointers.size < 2) pinch = null;
    drag = null;
  });

  canvas.addEventListener('wheel', function (e) {
    e.preventDefault();
    var p = posLokal(e);
    var d = e.deltaY;
    if (e.deltaMode === 1) d *= 16;
    else if (e.deltaMode === 2) d *= 100;
    zoomPada(p.x, p.y, Math.exp(-d * 0.0016));
  }, { passive: false });

  /* ============ Kontrol ============ */
  function formatKecepatan(v) {
    return v.toFixed(1).replace('.', ',') + '×';
  }

  btnJeda.addEventListener('click', function () {
    jeda = !jeda;
    btnJeda.textContent = jeda ? 'Lanjut' : 'Jeda';
    btnJeda.setAttribute('aria-pressed', String(jeda));
  });

  slider.addEventListener('input', function () {
    var v = parseFloat(slider.value);
    if (!isFinite(v)) v = 1;
    kecepatan = batas(v, 0.1, 8);
    elNilai.textContent = formatKecepatan(kecepatan);
    simpan('tataSurya.kecepatan', String(kecepatan));
  });

  btnZoomIn.addEventListener('click', function () { zoomPada(W / 2, H / 2, 1.3); });
  btnZoomOut.addEventListener('click', function () { zoomPada(W / 2, H / 2, 1 / 1.3); });

  btnPusat.addEventListener('click', function () {
    autoFit = true;
    cam.x = 0; cam.y = 0;
    cam.zoom = hitungZoomAwal();
    sembunyikanInfo();
  });

  btnTutup.addEventListener('click', sembunyikanInfo);

  /* Pulihkan kecepatan tersimpan */
  (function pulihkan() {
    var s = baca('tataSurya.kecepatan');
    if (s !== null) {
      var v = parseFloat(s);
      if (isFinite(v) && v >= 0.1 && v <= 8) {
        kecepatan = v;
        slider.value = String(v);
      }
    }
    elNilai.textContent = formatKecepatan(kecepatan);
  })();

  /* ============ Resolusi layar ============ */
  var tundaUkur = 0;
  function jadwalUkur() {
    if (tundaUkur) clearTimeout(tundaUkur);
    tundaUkur = setTimeout(function () { tundaUkur = 0; ukur(); }, 120);
  }
  window.addEventListener('resize', jadwalUkur);
  window.addEventListener('orientationchange', jadwalUkur);

  /* ============ Animasi ============ */
  function loop(now) {
    var dt = last ? (now - last) / 1000 : 0;
    last = now;
    if (dt > 0.05) dt = 0.05;
    if (dt < 0) dt = 0;

    if (!jeda) waktu += dt * kecepatan;

    hitungPosisi();
    gambar(now);

    requestAnimationFrame(loop);
  }

  ukur();
  hitungPosisi();
  requestAnimationFrame(loop);
})();
</script>
</body>
</html>
```

**Cek kebutuhan**
- **Matahari dan 8 planet mengorbit** → array `PLANET` (8 entri) + `gambarMatahari()` dan `gambarPlanet()` di dalam `gambar()`
- **Kecepatan relatif sesuai periode orbit, skala jarak tidak nyata tetapi urutan benar** → `p.omega = (Math.PI*2) / ((p.periode/365.25) * TAHUN_DETIK)`; nilai `orbit` naik berurutan 85 → 511
- **Bulan mengitari Bumi** → objek `BULAN`, perhitungan di `hitungPosisi()`, penggambaran di `gambarBulan()`, plus garis orbit bulan
- **Cincin Saturnus** → `gambarCincin()` dipanggil dua kali (belahan belakang sebelum badan planet, belahan depan sesudahnya) dengan `p.cincin: true`
- **Slider kecepatan waktu** → `<input id="kecepatan" type="range" min="0.1" max="8" step="0.1">` + listener `slider.addEventListener('input', …)`
- **Tombol jeda** → `#btnJeda` dengan handler `btnJeda.addEventListener('click', …)` yang membalik `jeda`
- **Zoom dengan scroll atau pinch** → `canvas.addEventListener('wheel', …)` dan blok `pinch` pada `pointerdown`/`pointermove`, keduanya memakai `zoomPada()`
- **Klik planet menampilkan info diameter, jarak, periode** → `pilihDi()` → `cariObjek()` → `tampilkanInfo()` mengisi `#infoDiameter`, `#infoJarak`, `#infoPeriode`
- **Responsif sampai 375 px** → media query `@media (max-width:460px)` dan `@media (max-width:620px)`; zoom awal dihitung dari `Math.min(W, H)`
- **Tanpa error JavaScript & akses localStorage dibungkus try/catch** → `simpan()` dan `baca()` memakai `try { window.localStorage… } catch (e) { … }`; semua `releasePointerCapture` juga dibungkus
- **Satu file HTML lengkap, tanpa sumber luar** → seluruh CSS ada di `<style>` dan JS di `<script>` dalam dokumen yang sama, tanpa library, font, atau gambar eksternal

**Catatan teknis**
Skala jarak memakai pemampatan pangkat (`orbit` 85–511 unit) sehingga Neptunus tetap masuk layar pada zoom awal. Rasio kecepatan antarplanet tetap mengikuti periode orbit sebenarnya, tetapi satu tahun Bumi dipetakan ke 8 detik dan periode Bulan dipercepat menjadi ±1,6 detik agar geraknya terlihat. Kecepatan waktu terakhir disimpan di localStorage dan dipulihkan saat halaman dibuka kembali. Interaksi memakai Pointer Events sehingga mouse, sentuh, dan cubit dua jari berbagi satu jalur kode.
